          facebook_posts: [],
          description:
            'Planning a trip to the beach to celebrate the coming of summer? These easy snacks will make sure you\'re fueled and ready for the next game of water polo. From <a href="https://tasty.co/recipe/garlic-parmesan-and-herb-pita-chips">parmesan garlic & herb pita chips</a> to super easy to make <a href="https://tasty.co/recipe/after-school-banana-roll-ups">banana roll-ups</a>, these treats are beach-friendly and hassle free. So what are you waiting for? Pack up your picnic basket with these goodies: summer\'s here! ',
