          created_at: 1640249938,
          description:
            'Living on your own can get overwhelming having to keep up with grocery lists and meal prepping all by yourself. And that\'s why we\'ve found just the right recipes that allow you to take it easy but also feel proud about taking care of yourself! The <a href="https://tasty.co/recipe/instant-noodle-lasagna-via-tasty-demais">instant noodle lasagna</a> is a twist on a lazy staple. And of course brownies are a must for your midnight munchy routine. This one just needs<a href="https://tasty.co/recipe/the-best-one-bowl-brownies">ONE bowl</a>! Bookmark this <a href="https://tasty.co/recipe/balsamic-chicken-and-veggies-meal-prep">balsamic chicken and veggies meal prep</a> recipe to meet your daily veggies and protein intake for busy weeks. Time for some adultin\'!',
