          description:
            'You should be taking advantage of these recipes especially when you\'re pressed for time in the kitchen! With these, you can whip up a divine <a href="https://tasty.co/recipe/spaghetti-squash-shrimp-scampi">garlic shrimp scampi</a> within 30 minutes. Want to make a quick lunch for office? Make a healthy <a href="https://tasty.co/recipe/thai-tofu-collard-wraps">thai tofu collard wraps</a> for lunch. Cooking has never been quicker!',
