          description:
            'This selection of 52 (!!) kid-friendly recipes is a lifesaver for all parents. You’ll find easy after-school snacks like <a href="https://tasty.co/recipe/pizza-chips">pizza chips</a>, healthy but delicious breakfasts like these <a href="https://tasty.co/recipe/pb-j-overnight-oats">PB&J overnight oats</a>, along with plenty of fun recipes to make with your kids for brunch or as a weekend activity. And fair warning: lots of these will be a big hit with the grownups, too!',
