          facebook_posts: [],
          description:
            'How much chocolate is too much chocolate? These easy and tasty chocolatey treats cover all the bases for the chocolate season. Kick it off with crowd-pleasing classics like a <a href="https://tasty.co/recipe/stuffed-chocolate-chip-cookies">Stuffed Chocolate Chip Cookie</a>, or try a modern and Instagram-ready treat like <a href="https://tasty.co/recipe/cookies-cream-cheesecake-bundt-cake">Cookies \'n Cream Cheesecake Bundt Cake</a>. Whatever you choose, just know that you can never go wrong with chocolate! ',
          created_at: 1619270071,
          language: "eng",
          draft_status: "published",
          thumbnail_url:
            "https://img.buzzfeed.com/thumbnailer-prod-us-east-1/video-api/assets/319052.jpg",
