          keywords: null,
          show: [
            {
              name: "Tasty",
              id: 17,
            },
          ],
          facebook_posts: [],
          description:
            'Mug cooking is one of the greatest boons of our existence. You can snap up a quick, yet delicious, meal all in one dish. This <a href="https://tasty.co/recipe/mug-baked-rigatoni">rigatoni</a> looks fancy AF, but comes out of a mug. Have frequent midnight cravings? Bookmark this <a href="https://tasty.co/recipe/pizza-in-a-mug">pizza in a mug</a> or check out these different <a href="https://tasty.co/compilation/3-minute-mug-cakes-4-ways">flavored mug cakes</a>. For busy mornings, we recommend this <a href="https://tasty.co/recipe/blueberry-french-toast-in-a-mug">blueberry french toast in a mug</a>. Get your mugs ready already!',
          created_at: 1657860554,
          language: "eng",
          draft_status: "published",
          thumbnail_url:
            "https://img.buzzfeed.com/thumbnailer-prod-us-east-1/video-api/assets/388593.jpg",
