          facebook_posts: [],
          description:
            'Calling all seafood lovers! Cooking fish and shellfish at home may seem intimidating — but it doesn\'t actually have to be. These easy <a href="https://tasty.co/recipe/popcorn-shrimp">popcorn shrimp</a>, for example, are ready in under 30 minutes and only need five ingredients. Or, if you\'re already a seafood pro, impress everyone with this gourmet-style <a href="https://tasty.co/recipe/gourmet-salmon-dinner">herb-crusted salmon</a>. Let’s get cooking!',
          created_at: 1519784561,
          language: "eng",
          draft_status: "published",
          thumbnail_url:
            "https://img.buzzfeed.com/thumbnailer-prod-us-east-1/video-api/assets/140113.jpg",
          thumbnail_alt_text: "",
          video_url: "https://vid.tasty.co/output/81544/hls24_1519783621.m3u8",
          approved_at: 1520132664,
