            'We\'ve curated a list of lip-smacking recipes that will make you \'gar-lick\' your fingers. The <a href="https://tasty.co/recipe/3-cheese-garlic-bread">3-cheese garlic bread</a> is a classic and great for a party or movie night. For a more decadent option, dig into the <a href="https://tasty.co/recipe/honey-garlic-slow-cooker-ribs">honey garlic slow cooker ribs</a>. The <a href="https://tasty.co/recipe/40-clove-garlic-chicken">40-clove garlic chicken</a> is also a must try. After all, we all know that there is no such thing as too much garlic!',
          created_at: 1615366779,
