          facebook_posts: [],
          description:
            'For meat lovers, breakfast is usually incomplete without some crispy bacon on the side with their morning eggs. The smoky flavor of the sliced meat along with its melting layers is a treat to dig into! Here\'s a guide to how you can create some amazing dishes using bacon. From <a href="https://tasty.co/recipe/cheesy-bacon-twists"> cheesy-bacon-twists </a> to href="https://tasty.co/recipe/bacon-wrapped-parmesan-garlic-knots"> bacon-wrapped-parmesan-garlic-knots </a>, we can safely say, "Bacon makes everything better!"',
          created_at: 1653039024,
          language: "eng",
          draft_status: "published",
          thumbnail_url:
            "https://img.buzzfeed.com/thumbnailer-prod-us-east-1/video-api/assets/378896.jpg",
