          description:
            'If you\'re looking for a taste of the cookies you had in your childhood, you\'ve come to the right place! Here are six homemade cookie recipes that will definitely remind you of the past. Whether you reach for classic <a href="https://tasty.co/recipe/the-best-chewy-chocolate-chip-cookies">chocolate chip cookies</a> or fan-favorite <a href="https://tasty.co/recipe/iced-oatmeal-cookies">iced oatmeal cookies</a>, all of these delicious treats are sure to leave you satisfied and full!',
