          facebook_posts: [],
          description:
            'What\'s better than making the best out of your most used kitchen essential: Mug! No pulling out 3 bowls, 2 pans for cooking and spending hours cleaning up the dishes. Take out your favourite mug because it\'s time for some <a href="thttps://tasty.co/recipe/pizza-in-a-mug">Pizza in a mug</a>. Feeling fancy? How about a <a href="https://tasty.co/recipe/mug-baked-rigatoni">Mug baked Rigatoni</a>. Craving something sweet at 2 AM? Whip up a <a href="https://tasty.co/recipe/chocolate-chip-muffin-mug">Chocolate Muffin</a> in just 2 mins! All you need is a mug!',
          created_at: 1652964663,
          language: "eng",
          draft_status: "published",
          thumbnail_url:
            "https://img.buzzfeed.com/thumbnailer-prod-us-east-1/video-api/assets/378572.jpg",
