          description:
            'Adulting is hard, and so is budgeting. From <a href="https://tasty.co/recipe/garlic-shrimp-scampi">garlic shrimp scampi</a> to <a href="https://tasty.co/recipe/chili-cheese-dog-boats">chili cheese dog boats</a>, these budget-friendly meals will keep you fueled without emptying out your wallet. Indulgent, comforting, and easy to throw together, these recipes are perfect when you need to feed yourself without spending a fortune! So what are you waiting for? Tuck away your wallet and let’s get cooking.',
