          created_at: 1615530227,
          description:
            'Let\'s be real, no one wants to make a mess and pull out all the stops in the kitchen late at night. But that doesn\'t mean you should sacrifice on flavor! These <a href="https://tasty.co/recipe/bbq-chicken-tenders">BBQ Tenders</a> come together with just 3 ingredients and they pack a punch. In fact, does our <a href="https://tasty.co/recipe/3-ingredient-strawberry-icebox-cake">Strawberry Icebox Cake</a>. Bookmark this for the next time you\'ve got the late night munchies! ',
