          show: [
            {
              name: "Tasty",
              id: 17,
            },
          ],
          created_at: 1617688772,
          description:
            'Having trouble meal-prepping? Not to fear, we\'ve brought you a weekly meal plan for an entire week with just 3 ingredients for each dish. For instance, tuck into a hearty <a href="https://tasty.co/recipe/tomato-avocado-egg-salad">Tomato Avocado Egg Salad</a> for a cozy Sunday at home. Take a glance and let us know which ones are your favorites! ',
