          description:
            'Thinking you want to switch into super healthy mode for a few weeks? We have got you covered for an entire month! Start your February with a super delicious <a href="https://tasty.co/recipe/protein-packed-buddha-bowl">protein-packed Buddha bowl</a>, then have <a href="https://tasty.co/recipe/healthy-banana-pancakes">banana pancakes</a> on first Sunday of the week. Stop brainstorming about what to eat and dig in and fill your mouth with these healthy and amazing recipes.',
