          created_at: 1665576254,
          description:
            'This NBA season has brought back all the excitement and thrill of basketball, and Tasty has brought some amazing recipes from "way downtown," as Mike Breen would say, which not only help you cheer on your favorite team and players, but also hit all the right tastebuds. We have <a href="https://tasty.co/recipe/new-york-city-dog">New York City Dog</a> for all the KD stans, a <a href="https://tasty.co/recipe/crunchy-california-roll-sushi-bowl">California Roll Sushi Bowl</a> for all the fans from LA, and plenty more! ',
          draft_status: "published",
