          description:
            'Exam season is, well, stressful: stress studying, stress coffee-guzzling, and stress-eating. We know it ALL too well, and we\'re here to help fuel those late night cram sessions with some much needed protein. Power through another lecture with our creamy <a href="https://tasty.co/recipe/java-chip-caffeinated-smoothie">Java Chip Milkshake</a>and munch on some healthy <a href="https://tasty.co/recipe/spicy-roasted-chickpeas">Spicy Roasted Chickpeas</a> to keep yourself ready to crush it. We bet you\'ll love \'em as much as we do!',
          draft_status: "published",
